// The session snapshot: every figure the band, the pane and the alerts draw from, written to `$.state` by
// the engine's events and only read by everything else. Ideas and cache/growth rules after ccOverhead
// (MIT, shengyy); the code is tidemark's own.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On, SessionContextBreakdown, SessionContextUsage, SessionRateLimit, Timer } from 'claude-code'

import type { TidemarkCacheStats, TidemarkConfigState, TidemarkLimit, TidemarkSnapshot, TidemarkTrack } from '../types'
import { EMPTY_ALERT_MEMORY, evaluateAlerts } from './alerts'
import { effectiveConfig } from './config-model'
import { LONG_TTL_MS as CACHE_TTL_MS, SHORT_TTL_MS, baseModel, defaultTtl, learnEffort, validCost } from './model-utils'
import type { EffortSupport } from './model-utils'
import { EMPTY_PROBES, applyProbeResult, planProbes } from './probes'
import type { ProbeOutcome, ProbeRequest } from './probes'
import { addAgentStep, notePath, pick, reduceCompact, reduceContext, reduceModelSwitch, reduceResumed, reduceStep, themeOf } from './snapshot-reducers'

export type Snapshot = TidemarkSnapshot

// Prompt-cache lifetimes: the short one, and the hour main conversations were seen to get.
export { SHORT_TTL_MS, LONG_TTL_MS as CACHE_TTL_MS } from './model-utils'
const TICK_MS = 30_000
const STORE_LIMITS = 'limits'
// What requests showed of each model's effort levels (EffortSupport); the band reads it under the same key.
export const STORE_EFFORTS = 'effortSupport'
// Each session's goal by session id (withGoal); the notes module writes it under the same key.
export const STORE_GOALS = 'goals'

const NO_STATS: TidemarkCacheStats = { input: 0, output: 0, read: 0, write: 0, last: 0 }
export const EMPTY_SNAPSHOT: Snapshot = {
  ctx: null, history: [], compactions: 0, compactionLog: [], breakdown: null, limits: [], limitsLive: false,
  limitsAt: null, cache: null, cacheTtl: null, ttlDefault: null, cacheStats: NO_STATS, model: null, effort: null, agents: [],
  activeAgents: 0, cost: null, turnCost: null, sessionId: null, startedAt: null, speed: null, theme: 'dark',
  goal: null, project: null,
}
const NO_TRACK: TidemarkTrack = { turnCostBase: null, turnStartedAt: null, turnOutput: 0 }

// Another module reads the snapshot through its own `atom({ plugin: 'tidemark', key: 'snapshot' }, EMPTY_SNAPSHOT)`:
// the engine wants atoms declared in the reading file and `$` never passed across an import.
const snapshotState = atom({ plugin: 'tidemark', key: 'snapshot' } as const, EMPTY_SNAPSHOT)
const track = atom({ plugin: 'tidemark', key: 'track' } as const, NO_TRACK)
const configState = atom({ plugin: 'tidemark', key: 'config' } as const, null as TidemarkConfigState | null)
const probesState = atom({ plugin: 'tidemark', key: 'probes' } as const, EMPTY_PROBES)
const alertsState = atom({ plugin: 'tidemark', key: 'alerts' } as const, EMPTY_ALERT_MEMORY)

// The snapshot as it stands; read while drawing, it redraws on every change.
export async function readSnapshot($: EngineInterface): Promise<Snapshot> {
  return read($, snapshotState)
}

const set = ($: EngineInterface, fn: (s: Snapshot) => Partial<Snapshot>) => update($, snapshotState, s => ({ ...s, ...fn(s) }))
const setTrack = ($: EngineInterface, fn: (t: TidemarkTrack) => Partial<TidemarkTrack>) => update($, track, t => ({ ...t, ...fn(t) }))

// Bumped by a conversation reset, so reads that started before it are dropped.
let revision = 0
let tick: Timer | undefined
let settling: Timer | undefined

async function readTheme($: EngineInterface) {
  const rows = await $.config.list().catch(() => [])
  const theme = themeOf(rows.find(row => row.key === 'theme')?.value)
  await set($, () => ({ theme }))
}

// A new conversation (/clear, /resume, /branch, another session id): its figures start over, the
// account's quota and the theme stay.
async function resetConversation($: EngineInterface, startedAt: number | null) {
  revision++
  await set($, s => ({ ...EMPTY_SNAPSHOT, limits: s.limits, theme: s.theme, sessionId: s.sessionId, model: s.model, startedAt, goal: s.goal, project: s.project }))
  await update($, track, () => NO_TRACK)
}

async function syncSession($: EngineInterface): Promise<boolean> {
  const r = revision
  const id = await $.session.id().catch(() => null)
  if (r !== revision || id === null) return false
  const previous = (await read($, snapshotState)).sessionId
  await set($, () => ({ sessionId: id }))
  const changed = previous !== null && previous !== id
  if (changed) await resetConversation($, await $.clock.now())
  if (previous !== id) {
    const goals = await $.store.get(STORE_GOALS).catch(() => undefined) as Record<string, string> | undefined
    await set($, () => ({ goal: goals?.[id] ?? null }))
  }
  return changed
}

async function setModel($: EngineInterface, id: string) {
  const at = await $.clock.now()
  await set($, s => reduceModelSwitch(s, id, at))
}

async function readModel($: EngineInterface) {
  const r = revision
  const id = await $.session.model().catch(() => null)
  if (r === revision && id) await setModel($, id)
}

async function takeCost($: EngineInterface, value: number | undefined) {
  const s = await read($, snapshotState)
  const previous = s.cost
  await set($, () => ({ cost: validCost(value) ? value : null }))
  if (!validCost(value) || (previous !== null && value < previous)) {
    await set($, () => ({ turnCost: null }))
    if (validCost(value)) await setTrack($, () => ({ turnCostBase: null }))
    return
  }
  const base = (await read($, track)).turnCostBase
  if (base !== null) await set($, () => ({ turnCost: value >= base ? value - base : null }))
}

// The session's own quota reading; shared through `$.store` only when its own figure changed, so an idle
// session never overwrites a newer one. `withdrawn`: an empty reading means the windows went away.
async function takeLimits($: EngineInterface, rateLimits: SessionRateLimit[] | undefined, withdrawn: boolean) {
  const live = pick(rateLimits)
  if (live.length === 0 && !withdrawn) return
  const s = await read($, snapshotState)
  const changed = !s.limitsLive || JSON.stringify(live) !== JSON.stringify(s.limits)
  // `limitsAt` is the last reading, changed or not: a figure that holds still is still fresh.
  const at = await $.clock.now()
  await set($, () => ({ limits: live, limitsLive: true, limitsAt: at }))
  if (changed) await $.store.set(STORE_LIMITS, live).catch(() => undefined)
}

async function localBreakdown($: EngineInterface): Promise<SessionContextBreakdown | undefined> {
  try {
    return (await $.session.usage({ breakdown: 'summary' })).context.breakdown
  } catch {
    return undefined
  }
}

async function takeContext($: EngineInterface, context: SessionContextUsage | undefined, recordGrowth: boolean, r: number) {
  const b = await localBreakdown($)
  if (r !== revision) return
  await set($, s => reduceContext(s, context, recordGrowth, b))
}

// The engine's figures now; quota from `$.store` until this session has its own.
async function load($: EngineInterface, recordGrowth = false) {
  await syncSession($)
  const r = revision
  const usage = await $.session.usage().catch(() => undefined)
  if (!usage || r !== revision) return
  await readModel($)
  if (r !== revision) return
  if (usage.startedAt > 0 && (await read($, snapshotState)).startedAt === null) await set($, () => ({ startedAt: usage.startedAt }))
  await takeCost($, usage.cost?.usd)
  await takeContext($, usage.context, recordGrowth, r)
  if (r !== revision) return
  await takeLimits($, usage.rateLimits, false)
  await readTtlDefault($, pick(usage.rateLimits))
  if (pick(usage.rateLimits).length === 0 && !(await read($, snapshotState)).limitsLive) {
    const saved = await $.store.get(STORE_LIMITS).catch(() => undefined)
    if (r === revision && Array.isArray(saved)) await set($, () => ({ limits: saved as TidemarkLimit[] }))
  }
}

// What Claude Code asks for by its environment, settings and account; read on every load, cheap.
async function readTtlDefault($: EngineInterface, limits: TidemarkLimit[]) {
  const env = {
    force5m: await $.env.get('FORCE_PROMPT_CACHING_5M').catch(() => undefined),
    ttl: await $.env.get('CLAUDE_CODE_PROMPT_CACHE_TTL').catch(() => undefined),
    enable1h: await $.env.get('ENABLE_PROMPT_CACHING_1H').catch(() => undefined),
  }
  const settings = await $.settings.read().catch(() => ({}) as Record<string, unknown>)
  const ttlDefault = defaultTtl(env, (settings as Record<string, unknown>).promptCacheTtl, limits)
  if ((await read($, snapshotState)).ttlDefault !== ttlDefault) await set($, () => ({ ttlDefault }))
}

async function readActiveAgents($: EngineInterface) {
  const r = revision
  const list = await $.agent.list().catch(() => [])
  if (r !== revision) return
  const count = list.filter(a => a.status === 'running').length
  await set($, s => ({
    activeAgents: count,
    agents: s.agents.map(agent => {
      const info = list.find(a => a.id === agent.id)
      return info ? { ...agent, label: info.type, ...(info.description !== undefined && { description: info.description }) } : agent
    }),
  }))
}

// The engine installs readings after the hook returns; one coalesced read picks them up.
function refreshSoon($: EngineInterface) {
  settling?.cancel()
  settling = $.clock.after(100, async () => {
    await readActiveAgents($)
    await load($).catch(logTo($, 'load'))
  })
}

async function resumed($: EngineInterface, e: { context_tokens?: number; seconds_since_last_response?: number; prompt_cache_likely_expired?: boolean }) {
  const { context_tokens: tokens, seconds_since_last_response: age, prompt_cache_likely_expired: expired } = e
  const at = age !== undefined ? (await $.clock.now()) - age * 1000 : undefined
  await set($, s => reduceResumed(s, { tokens, age, expired, at }))
}

// What a request sent against the level asked for, kept per Claude Code version in the plugin store.
async function learnEfforts($: EngineInterface, model: string, asked: string, sent: string | number | undefined) {
  const version = (await $.session.version()).version
  const saved = await $.store.get(STORE_EFFORTS) as EffortSupport | undefined
  const next = learnEffort(saved, version, model, asked, sent)
  if (JSON.stringify(next) !== JSON.stringify(saved)) await $.store.set(STORE_EFFORTS, next)
}

// Probe keys with a request in flight: a key never runs twice at once.
const running = new Set<string>()

// A failure the band survives goes to the debug log (`claude --debug`), led by the plugin's name.
const logTo = ($: EngineInterface, where: string) => (err: unknown) =>
  $.ui.log(`${where}: ${err instanceof Error ? err.message : String(err)}`, { to: 'debug' })

async function runProbe($: EngineInterface, req: ProbeRequest, cwd: string): Promise<ProbeOutcome> {
  try {
    if (req.kind === 'process') {
      const r = await $.process.run(req.argv, { cwd, timeoutMs: req.timeoutMs, ...(req.stdin !== undefined && { stdin: req.stdin }), ...(req.env && { env: req.env }) })
      return r.exitCode === 0 ? { ok: true, stdout: r.stdout } : { ok: false, error: r.stderr.trim() || `exit ${r.exitCode}` }
    }
    let timer: Timer | undefined
    const timeout = new Promise<never>((_, reject) => { timer = $.clock.after(req.timeoutMs, () => reject(new Error('timeout'))) })
    try {
      // The one request tidemark makes itself; the address stays literal so a reader of the call sees the host.
      const r = await Promise.race([$.http.fetch('https://status.claude.com/api/v2/summary.json'), timeout])
      return { ok: true, text: r.text, status: r.status }
    } finally {
      timer?.cancel()
    }
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) }
  }
}

// Runs what the probes module plans, without holding the caller: each result lands in the `probes` atom.
async function probe($: EngineInterface, trigger: 'tick' | 'turn') {
  const { config } = effectiveConfig(await read($, configState))
  const cwd = await $.session.cwd().catch(() => '')
  const now = await $.clock.now()
  const plan = planProbes(config, await read($, probesState), await read($, snapshotState), cwd, now, trigger)
  for (const req of plan) {
    if (running.has(req.key)) continue
    running.add(req.key)
    void runProbe($, req, cwd).then(async outcome => {
      const at = await $.clock.now()
      await update($, probesState, p => applyProbeResult(p, req.key, outcome, at))
    }).catch(logTo($, `probe ${req.key}`)).finally(() => running.delete(req.key))
  }
}

// Threshold toasts from the alerts module; its memory kept in the `alerts` atom.
async function alert($: EngineInterface) {
  const { config } = effectiveConfig(await read($, configState))
  const now = await $.clock.now()
  const { toasts, memory } = evaluateAlerts(await read($, snapshotState), config, await read($, alertsState), now)
  await update($, alertsState, () => memory)
  for (const text of toasts) $.ui.toast(text)
}

async function snapshotStart($: EngineInterface): Promise<void> {
    tick?.cancel()
    tick = $.clock.every(TICK_MS, async () => {
      await load($).catch(logTo($, 'tick load'))
      await readActiveAgents($).catch(logTo($, 'tick agents'))
      await probe($, 'tick').catch(logTo($, 'tick probe'))
      await alert($).catch(logTo($, 'tick alert'))
      $.ui.invalidate('ui.render')
    })
    if ((await read($, snapshotState)).startedAt === null) {
      const now = await $.clock.now()
      await set($, () => ({ startedAt: now }))
    }
    const cwd = await $.session.cwd().catch(() => null)
    const note = cwd ? (await $.fs.read(notePath(cwd)).catch(() => '')).trim() : ''
    if (note) await set($, () => ({ project: note }))
    await readTheme($)
    await readActiveAgents($)
    await load($)
}

async function snapshotTurnStart($: EngineInterface): Promise<void> {
    await syncSession($)
    const r = revision
    const reading = await $.session.usage().catch(() => undefined)
    const now = await $.clock.now()
    if (r !== revision) return
    await setTrack($, () => ({ turnCostBase: validCost(reading?.cost?.usd) ? reading.cost.usd : null, turnStartedAt: now, turnOutput: 0 }))
    await set($, () => ({ turnCost: null }))
}

async function snapshotTurnComplete($: EngineInterface): Promise<void> {
    const r = revision
    await readActiveAgents($)
    refreshSoon($)
    const ledger = await $.session.usage().catch(() => undefined)
    if (r === revision) await takeCost($, ledger?.cost?.usd)
    await probe($, 'turn').catch(logTo($, 'turn probe'))
}

// The snapshot owns session.start, turn.start and turn.complete: the engine takes one hook per event per
// plugin. The commands are registered here, at session start, for the modules that answer them; their names
// stay literal so `claude plugin validate` sees each `command.run` hook answers a command of this mod.
export function registerSnapshot(on: On): void {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    // Session state outlives a reload of the mod: a snapshot an older version stored gets the newer fields.
    await set($, s => ({ ...EMPTY_SNAPSHOT, ...s })).catch(logTo($, 'session.start state'))
    await snapshotStart($).catch(logTo($, 'session.start'))
    // A host that registers no commands still draws the band.
    await $.command.register({ name: 'tidemark', description: 'Show tidemark details: context, cache, quota, agents' }).catch(logTo($, 'register /tidemark'))
    await $.command.register({ name: 'tidemark-config', description: 'Edit the tidemark band: widgets, style, presets' }).catch(logTo($, 'register /tidemark-config'))
    await $.command.register({ name: 'tidemark-goal', description: 'Set the goal the band shows for this session; without text opens a field' }).catch(logTo($, 'register /tidemark-goal'))
    await $.command.register({ name: 'tidemark-project', description: 'Set the project name the band shows in this directory; without text opens a field' }).catch(logTo($, 'register /tidemark-project'))
    return result
  })

  on('turn.start', async ($, e, next) => {
    await snapshotTurnStart($).catch(logTo($, 'turn.start'))
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    await snapshotTurnComplete($).catch(logTo($, 'turn.complete'))
    return result
  })

  // /clear, /resume and /branch start another conversation with no new session.start.
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($, e, next) => {
    try {
      return await next(e)
    } finally {
      await resetConversation($, await $.clock.now())
      await load($)
      if (e.source !== 'clear') await resumed($, e)
    }
  })

  // After each main turn and when a quota window moves.
  on('session.measure', async ($, e, next) => {
    const r = revision
    const result = await next(e)
    if (r !== revision) return result
    await syncSession($)
    if (r !== revision) return result
    await readModel($)
    await takeCost($, e.cost?.usd)
    await takeContext($, e.context, true, r)
    if (r === revision) await takeLimits($, e.rateLimits, e.changed.includes('rateLimits'))
    await alert($).catch(logTo($, 'alert'))
    return result
  })

  // A main compaction: counted, growth starts over, the next request writes a new conversation.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined && e.trigger !== 'precompute' && result.skip === undefined) {
      await set($, s => reduceCompact(s, result.tokensBefore, result.tokensAfter))
      refreshSoon($)
    }
    return result
  })

  on('classic.PostModelSwitch', async ($, e, next) => {
    const result = await next(e)
    await setModel($, e.to_model)
    await set($, () => ({ cacheTtl: e.cache_ttl === '5m' ? SHORT_TTL_MS : CACHE_TTL_MS }))
    refreshSoon($)
    return result
  })

  on('agent.spawn', async ($, e, next) => {
    const result = await next(e)
    await readActiveAgents($)
    refreshSoon($)
    return result
  })

  // Each request: main ones feed the cache, effort and speed; a subagent's feed its own entry.
  on('turn.step', async function* ($, e, next) {
    const r = revision
    const started = await $.clock.now()
    const result = yield* next(e)
    if (r !== revision) return result
    const u = result.usage
    if (!u) return result
    const effort = baseModel(e.model) === baseModel(u.model) ? e.effort : undefined
    if (e.agentId === undefined) {
      await syncSession($)
      if (r !== revision) return result
      await setModel($, u.model)
      const now = await $.clock.now()
      const t = await read($, track)
      const output = t.turnOutput + (u.output_tokens ?? 0)
      await setTrack($, () => ({ turnOutput: output, effortAsked: null }))
      if (t.effortAsked) await learnEfforts($, u.model, t.effortAsked, effort).catch(logTo($, 'effort support'))
      const seconds = t.turnStartedAt !== null ? (now - t.turnStartedAt) / 1000 : 0
      await set($, s => reduceStep(s, u, e.turnId, started, effort ?? null, output, seconds))
      refreshSoon($)
    } else {
      const id = e.agentId
      await set($, s => ({ agents: addAgentStep(s.agents, id, u.model, u, effort) }))
    }
    await readActiveAgents($)
    return result
  })

  on('command.run', { command: ['clear', 'resume', 'branch', 'model', 'autocompact', 'theme', 'effort'] }, async ($, e, next) => {
    const result = await next(e)
    // The level asked for, held until the next main request shows what the model was sent.
    if (e.command === 'effort') await setTrack($, () => ({ effortAsked: e.args.trim() || null }))
    if (e.command === 'theme') await readTheme($)
    refreshSoon($)
    return result
  })

  on('config.set', { key: ['theme', 'autoCompact'] }, async ($, e, next) => {
    const result = await next(e)
    if (result.deny === undefined) {
      if (e.key === 'theme') await set($, () => ({ theme: themeOf(result.value) }))
      else refreshSoon($)
    }
    return result
  })
}

files.hooks/config-model.ts:
// The config model, pure: schema v1, the default, the presets, validation, merging the files' texts and
// what Save writes. Loading, hand-edit checks and the atom live in the config hooks.
import type { TidemarkConfig, TidemarkConfigState, TidemarkSectionId, TidemarkWidgetId, TidemarkWidgetItem } from '../types'

export type Config = TidemarkConfig
export type WidgetId = TidemarkWidgetId
export type WidgetItem = TidemarkWidgetItem
export type LoadedConfig = { config: Config; warnings: string[]; error?: string; sources: string[] }

// What an option takes; `default` is what a widget uses when the option is absent.
export type OptionSpec =
  | { kind: 'bool'; default: boolean }
  | { kind: 'enum'; values: readonly string[]; default: string }
  | { kind: 'int'; min: number; max: number; default: number }
  | { kind: 'string'; default: string }
  | { kind: 'strings'; default: readonly string[] }

const bool = (d: boolean): OptionSpec => ({ kind: 'bool', default: d })
const int = (min: number, max: number, d: number): OptionSpec => ({ kind: 'int', min, max, default: d })
const choice = (values: readonly string[], d: string): OptionSpec => ({ kind: 'enum', values, default: d })
const MODE = choice(['used', 'left'], 'used')
const QUOTA = { mode: MODE, showReset: bool(true), bar: bool(false) }

// Each widget's own options. TTLs are in seconds, timeouts in milliseconds.
export const WIDGET_OPTIONS: Record<WidgetId, Record<string, OptionSpec>> = {
  context: { mode: MODE, barWidth: int(4, 20, 10), showTokens: bool(true), showGrowth: bool(true), showLast: bool(true) },
  cache: { showRewrite: bool(true), showMinutes: bool(true), ttl: choice(['auto', '5m', '1h'], 'auto') },
  quota5h: QUOTA,
  quota7d: QUOTA,
  cost: {},
  agents: {},
  goal: {},
  project: {},
  model: { showEffort: bool(true), format: choice(['short', 'full'], 'short'), cycle: { kind: 'strings', default: [] } },
  git: { showDirty: bool(true), showDiff: bool(true), showSync: bool(true), maxLength: int(4, 200, 24), ttl: int(1, 3600, 5), fetch: int(0, 86_400, 300) },
  cwd: { style: choice(['project', 'basename', 'short', 'full'], 'project') },
  sessionTime: {},
  compactions: { hideZero: bool(true) },
  tokenSpeed: {},
  command: { command: { kind: 'string', default: '' }, maxWidth: int(4, 200, 40), timeout: int(100, 30_000, 2000), ttl: int(1, 3600, 10) },
  claudeStatus: { ttl: int(30, 3600, 300) },
  gitPr: { githubHosts: { kind: 'strings', default: [] }, ttl: int(10, 3600, 120) },
  flex: {},
  compact: {},
  actions: { config: bool(true) },
}

export const WIDGET_IDS = Object.keys(WIDGET_OPTIONS) as WidgetId[]
const SECTION_IDS: TidemarkSectionId[] = ['context', 'cacheQuota', 'agents']
export const SEPARATORS = ['pipe', 'space', 'dot', 'powerline', 'custom'] as const
export const ICONS = ['text', 'nerd'] as const
export const MAX_LINES = 3
// The highest value of each alert threshold: percentages, and the cache warning in seconds.
export const ALERT_MAX = { context: 100, quota5h: 100, quota7d: 100, cacheSeconds: 3600 } as const
// The context share from which the band offers `/compact`: a heuristic, not a documented figure:
// answers degrade as the window fills and auto-compaction waits until it is nearly full (967k of 1M).
export const COMPACT_AT = 70

// Where editors fetch `config.schema.json`, the JSON Schema of a config file; Save writes it as `$schema`.
export const SCHEMA_URL = 'https://raw.githubusercontent.com/VizzleTF/claude-skills/main/plugins/tidemark/config.schema.json'

const items = (...ids: WidgetId[]): WidgetItem[] => ids.map(widget => ({ widget }))

export const DEFAULT_CONFIG: Config = {
  version: 1,
  lines: [items('project', 'context', 'compact', 'cache', 'flex', 'quota5h', 'quota7d', 'flex', 'sessionTime', 'git', 'model', 'cwd', 'actions')],
  style: { separator: 'space', icons: 'nerd' },
  pane: { sections: SECTION_IDS.map(id => ({ id, enabled: true })) },
  alerts: { enabled: false, context: 80, quota5h: 90, quota7d: 90, cacheSeconds: 60 },
  compact: { enabled: true, at: COMPACT_AT },
}

const preset = (lines: WidgetItem[][], style: Config['style'] = DEFAULT_CONFIG.style): Config => ({ ...DEFAULT_CONFIG, lines, style })

export const PRESETS: Record<string, Config> = {
  minimal: preset([items('context', 'quota5h')]),
  classic: preset([items('context', 'cache', 'quota5h', 'quota7d')]),
  default: DEFAULT_CONFIG,
  full: preset([
    items('project', 'goal', 'context', 'cache', 'quota5h', 'quota7d', 'cost'),
    items('model', 'cwd', 'git', 'sessionTime', 'compactions', 'tokenSpeed', 'agents'),
  ]),
  powerline: preset(DEFAULT_CONFIG.lines, { separator: 'powerline', icons: 'nerd' }),
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

function optionOk(spec: OptionSpec, v: unknown): boolean {
  switch (spec.kind) {
    case 'bool': return typeof v === 'boolean'
    case 'enum': return typeof v === 'string' && spec.values.includes(v)
    case 'int': return Number.isInteger(v) && (v as number) >= spec.min && (v as number) <= spec.max
    case 'string': return typeof v === 'string'
    case 'strings': return Array.isArray(v) && v.every(s => typeof s === 'string')
  }
}

function validItem(raw: unknown, where: string, warn: (m: string) => void): WidgetItem | undefined {
  const obj = typeof raw === 'string' ? { widget: raw } : raw
  if (!isObject(obj) || typeof obj.widget !== 'string' || !Object.hasOwn(WIDGET_OPTIONS, obj.widget)) {
    warn(`${where}: unknown widget ${JSON.stringify(isObject(obj) ? obj.widget : obj)}`)
    return undefined
  }
  const widget = obj.widget as WidgetId
  const item: WidgetItem = { widget }
  for (const [key, v] of Object.entries(obj)) {
    if (key === 'widget') continue
    if (key === 'enabled' && typeof v === 'boolean') item.enabled = v
    else if (key === 'label' && (typeof v === 'string' || v === null)) item.label = v
    else if (key === 'priority' && Number.isInteger(v) && (v as number) >= 0 && (v as number) <= 1000) item.priority = v as number
    else if (key === 'options' && isObject(v)) {
      const specs = WIDGET_OPTIONS[widget]
      const options: Record<string, unknown> = {}
      for (const [name, value] of Object.entries(v)) {
        const spec = Object.hasOwn(specs, name) ? specs[name] : undefined
        if (!spec) warn(`${where} ${widget}: unknown option ${name}`)
        else if (!optionOk(spec, value)) warn(`${where} ${widget}: invalid ${name} ${JSON.stringify(value)}`)
        else options[name] = value
      }
      if (Object.keys(options).length > 0) item.options = options
    } else warn(`${where} ${widget}: invalid ${key} ${JSON.stringify(v)}`)
  }
  return item
}

// A raw value (parsed JSON) to a config: anything unknown or invalid is dropped with a warning and the
// default stands in its place.
export function validate(raw: unknown): { config: Config; warnings: string[] } {
  const warnings: string[] = []
  const warn = (m: string) => warnings.push(m)
  const src = isObject(raw) ? raw : {}
  if (!isObject(raw)) warn('config is not an object')
  if (src.version !== undefined && src.version !== 1) warn(`unsupported version ${JSON.stringify(src.version)}`)

  let lines = DEFAULT_CONFIG.lines
  if (src.lines !== undefined) {
    if (!Array.isArray(src.lines)) warn('lines: not a list')
    else {
      if (src.lines.length > MAX_LINES) warn(`lines: only the first ${MAX_LINES} are used`)
      const got = src.lines.slice(0, MAX_LINES).map((line, i) => {
        if (!Array.isArray(line)) {
          warn(`line ${i + 1}: not a list`)
          return []
        }
        return line.map(item => validItem(item, `line ${i + 1}`, warn)).filter(item => item !== undefined)
      }).filter(line => line.length > 0)
      if (got.length > 0) lines = got
      else warn('lines: no widgets, the default is used')
    }
  }

  const style = { ...DEFAULT_CONFIG.style }
  if (src.style !== undefined) {
    const s = isObject(src.style) ? src.style : {}
    if (!isObject(src.style)) warn('style: not an object')
    for (const [key, v] of Object.entries(s)) {
      if (key === 'separator' && SEPARATORS.includes(v as never)) style.separator = v as Config['style']['separator']
      else if (key === 'icons' && ICONS.includes(v as never)) style.icons = v as Config['style']['icons']
      else if (key === 'custom' && typeof v === 'string') style.custom = v
      else if (key === 'buttons' && typeof v === 'boolean') style.buttons = v
      else warn(`style: invalid ${key} ${JSON.stringify(v)}`)
    }
  }

  let pane = DEFAULT_CONFIG.pane
  if (src.pane !== undefined) {
    const sections = isObject(src.pane) && Array.isArray(src.pane.sections) ? src.pane.sections : undefined
    if (!sections) warn('pane: sections must be a list')
    else {
      const seen = new Set<string>()
      const got: Config['pane']['sections'] = []
      for (const s of sections) {
        if (isObject(s) && SECTION_IDS.includes(s.id as never) && !seen.has(s.id as string)) {
          seen.add(s.id as string)
          got.push({ id: s.id as TidemarkSectionId, enabled: s.enabled !== false })
        } else warn(`pane: invalid section ${JSON.stringify(s)}`)
      }
      pane = { sections: got }
    }
  }

  const alerts = { ...DEFAULT_CONFIG.alerts }
  if (src.alerts !== undefined) {
    const a = isObject(src.alerts) ? src.alerts : {}
    if (!isObject(src.alerts)) warn('alerts: not an object')
    for (const [key, v] of Object.entries(a)) {
      const max = ALERT_MAX[key as keyof typeof ALERT_MAX]
      if (key === 'enabled' && typeof v === 'boolean') alerts.enabled = v
      else if (key !== 'enabled' && Object.hasOwn(alerts, key) && typeof v === 'number' && v >= 0 && v <= max) (alerts as Record<string, unknown>)[key] = v
      else warn(`alerts: invalid ${key} ${JSON.stringify(v)}`)
    }
  }

  const compact = { ...DEFAULT_CONFIG.compact }
  if (src.compact !== undefined) {
    const c = isObject(src.compact) ? src.compact : {}
    if (!isObject(src.compact)) warn('compact: not an object')
    for (const [key, v] of Object.entries(c)) {
      if (key === 'enabled' && typeof v === 'boolean') compact.enabled = v
      else if (key === 'at' && Number.isInteger(v) && (v as number) >= 1 && (v as number) <= 100) compact.at = v as number
      else warn(`compact: invalid ${key} ${JSON.stringify(v)}`)
    }
  }

  for (const key of Object.keys(src)) {
    if (!['$schema', 'version', 'lines', 'style', 'pane', 'alerts', 'compact'].includes(key)) warn(`unknown key ${key}`)
  }
  return { config: { version: 1, lines, style, pane, alerts, compact }, warnings }
}

// Where the files are: `$XDG_CONFIG_HOME/tidemark/config.json` (else `$HOME/.config/...`) and the session
// directory's `.claude/tidemark.json`. Null where the place cannot be known.
export function configPathsFrom(env: { xdg?: string; home?: string; cwd?: string }): ConfigPaths {
  const { xdg, home, cwd } = env
  const base = xdg ? xdg : home ? `${home.replace(/\/$/, '')}/.config` : undefined
  return {
    global: base ? `${base.replace(/\/$/, '')}/tidemark/config.json` : null,
    project: cwd ? `${cwd.replace(/\/$/, '')}/.claude/tidemark.json` : null,
  }
}

export type ConfigPaths = { global: string | null; project: string | null }

// The files' texts (global first, a missing file left out) to the config in effect: the project file's
// top-level keys over the global's, validated. A file that does not parse is skipped and named in `error`.
export function loadFromTexts(files: ({ path: string; text: string } | { path: string; error: string })[]): LoadedConfig {
  let merged: Record<string, unknown> = {}
  const sources: string[] = []
  const errors: string[] = []
  for (const file of files) {
    const { path } = file
    let raw: unknown
    try {
      if ('error' in file) throw new Error(file.error)
      raw = JSON.parse(file.text)
    } catch (err) {
      errors.push(`${path}: ${err instanceof Error ? err.message : String(err)}`)
      continue
    }
    if (!isObject(raw)) {
      errors.push(`${path}: not a JSON object`)
      continue
    }
    if (raw.version !== undefined && raw.version !== 1) {
      errors.push(`${path}: unsupported version ${JSON.stringify(raw.version)}`)
      continue
    }
    merged = { ...merged, ...raw }
    sources.push(path)
  }
  const { config, warnings } = validate(merged)
  return { config, warnings, sources, ...(errors.length > 0 && { error: errors.join('; ') }) }
}

// What Save writes to `target`, so each file keeps to its own keys (the project file's over the global's):
// to the global file, a top-level key the project file overrides and the draft left as loaded keeps the
// global file's value; to the project file, only the keys it already has and those where the draft differs
// from the global file. `globalOnly` is the global file alone, validated.
export function saveContent(draft: Config, loaded: Config, globalOnly: Config, projectKeys: string[], target: 'global' | 'project'): Record<string, unknown> {
  const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)
  const keys = ['lines', 'style', 'pane', 'alerts', 'compact'] as const
  const out: Record<string, unknown> = { $schema: SCHEMA_URL, version: 1 }
  for (const k of keys) {
    if (target === 'global') out[k] = projectKeys.includes(k) && same(draft[k], loaded[k]) ? globalOnly[k] : draft[k]
    else if (projectKeys.includes(k) || !same(draft[k], globalOnly[k])) out[k] = draft[k]
  }
  return out
}

// What a saved file holds.
export const configText = (config: Config | Record<string, unknown>) => `${JSON.stringify(config, null, 2)}\n`

// The config a `configState` value stands for: the default until the first load.
export function effectiveConfig(s: TidemarkConfigState | null): LoadedConfig {
  if (!s) return { config: DEFAULT_CONFIG, warnings: [], sources: [] }
  const { stamp: _, ...loaded } = s
  // Session state outlives a reload of the mod, so a config an older version stored lacks newer keys.
  return { ...loaded, config: { ...DEFAULT_CONFIG, ...loaded.config } }
}

