// External probes (git, gh/glab, a command, the Claude status page) as pure planning: the snapshot module
// runs what `planProbes` asks for and folds each outcome back with `applyProbeResult`. Nothing here calls
// `$`; the engine only lets the hook's own file do that.
import type { TidemarkConfig, TidemarkProbes, TidemarkSnapshot, TidemarkWidgetId, TidemarkWidgetItem } from '../types'
import { WIDGET_OPTIONS } from './config-model'
import { opt as optionOf } from './widgets/kit'

export type ProbesState = TidemarkProbes

export type ProbeRequest =
  | { key: string; kind: 'process'; argv: string[]; stdin?: string; timeoutMs: number; env?: Record<string, string> }
  | { key: string; kind: 'status'; timeoutMs: number }

export type ProbeOutcome = { ok: true; stdout?: string; text?: string; status?: number } | { ok: false; error: string }

export const EMPTY_PROBES: ProbesState = {}

// Fixed limits the config has no option for.
const GIT_TIMEOUT_MS = 2_000
const FETCH_TIMEOUT_MS = 15_000
const GIT_ROOT_TTL_S = 60
const PR_TIMEOUT_MS = 10_000
const STATUS_TIMEOUT_MS = 5_000

const GIT = ['git', '--no-optional-locks']

// The host of a remote URL: `git@host:o/r`, `https://host/o/r`, `ssh://git@host:22/o/r`.
const remoteHost = (url: string) => /^(?:[a-z][a-z0-9+.-]*:\/\/)?(?:[^@/]+@)?([^/:]+)/i.exec(url.trim())?.[1]?.toLowerCase() ?? ''

// The key a command's result lives under.
export const commandKey = (command: string) => `command:${command}`

// The requests due now: only for enabled widgets that need them, each when its result is older than its TTL.
// git refreshes on every completed turn as well.
export function planProbes(
  config: TidemarkConfig, probes: ProbesState, snap: TidemarkSnapshot, cwd: string, now: number, trigger: 'tick' | 'turn',
): ProbeRequest[] {
  const items = config.lines.flat().filter(i => i.enabled !== false)
  const first = (id: TidemarkWidgetId) => items.find(i => i.widget === id)
  const opt = <T>(item: TidemarkWidgetItem, name: string) => optionOf<T>({ options: WIDGET_OPTIONS[item.widget] }, item, name)
  const due = (key: string, ttlS: number) => now - (probes[key]?.at ?? -Infinity) >= ttlS * 1000
  const out: ProbeRequest[] = []
  const run = (key: string, ttlS: number, argv: string[], timeoutMs: number, stdin?: string, env?: Record<string, string>) => {
    if (due(key, ttlS) && !out.some(r => r.key === key)) out.push({ key, kind: 'process', argv, timeoutMs, ...(stdin !== undefined && { stdin }), ...(env && { env }) })
  }

  const dir = items.find(i => i.widget === 'cwd' && opt(i, 'style') === 'project')
  if (dir) run('gitRoot', GIT_ROOT_TTL_S, ['git', 'rev-parse', '--show-toplevel'], GIT_TIMEOUT_MS)

  // The PR widget needs the branch too, to drop a PR of the branch left.
  const git = first('git')
  const pr = first('gitPr')
  if (git || pr) {
    const ttl = trigger === 'turn' ? 0 : git ? opt<number>(git, 'ttl') : (WIDGET_OPTIONS.git.ttl!.default as number)
    // A fetch that landed since the last status makes the status due: it holds the new ahead/behind.
    const fetched = (probes.gitFetch?.at ?? -Infinity) > (probes.gitStatus?.at ?? -Infinity)
    run('gitStatus', fetched ? 0 : ttl, [...GIT, 'status', '--porcelain=v2', '--branch'], GIT_TIMEOUT_MS)
    // The remote's side of ahead/behind is only as fresh as the last fetch; a credential prompt fails instead of waiting.
    const every = git ? opt<number>(git, 'fetch') : 0
    if (git && every > 0 && opt(git, 'showSync')) run('gitFetch', every, [...GIT, 'fetch', '--quiet', '--no-tags'], FETCH_TIMEOUT_MS, undefined, { GIT_TERMINAL_PROMPT: '0' })
    if (git && opt(git, 'showDiff')) run('gitDiff', ttl, [...GIT, 'diff', '--numstat', 'HEAD'], GIT_TIMEOUT_MS)
  }

  if (pr) {
    const ttl = opt<number>(pr, 'ttl')
    run('gitRemote', ttl, ['git', 'remote', 'get-url', 'origin'], GIT_TIMEOUT_MS)
    const remote = probes.gitRemote?.stdout
    if (remote) {
      const host = remoteHost(remote)
      const github = host === 'github.com' || opt<string[]>(pr, 'githubHosts').some(h => h.toLowerCase() === host)
      run('gitPr', ttl, github ? ['gh', 'pr', 'view', '--json', 'number,state,statusCheckRollup,headRefName,url'] : ['glab', 'mr', 'view', '-F', 'json'], PR_TIMEOUT_MS)
    }
  }

  for (const item of items.filter(i => i.widget === 'command')) {
    const command = opt<string>(item, 'command').trim()
    if (!command) continue
    const stdin = JSON.stringify({ sessionId: snap.sessionId, model: snap.model, cwd, contextPercent: snap.ctx?.percent ?? null })
    run(commandKey(command), opt(item, 'ttl'), ['sh', '-c', command], opt(item, 'timeout'), stdin)
  }

  const status = first('claudeStatus')
  if (status && due('claudeStatus', opt(status, 'ttl'))) out.push({ key: 'claudeStatus', kind: 'status', timeoutMs: STATUS_TIMEOUT_MS })
  return out
}

// One finished request folded into the state. A failure (an HTTP error status included) keeps the last
// result beside the error; a success replaces both.
export function applyProbeResult(probes: ProbesState, key: string, outcome: ProbeOutcome, now: number): ProbesState {
  if (outcome.ok && !(outcome.status !== undefined && outcome.status >= 400)) {
    const { ok: _, ...result } = outcome
    return { ...probes, [key]: { at: now, ...result } }
  }
  const error = outcome.ok ? `http ${outcome.status}` : outcome.error
  const { error: _, at: __, ...last } = probes[key] ?? { at: now }
  return { ...probes, [key]: { at: now, ...last, error } }
}

files.hooks/editor-model.ts:
// The config editor's edits as pure functions on a draft config: move, toggle, remove and add widgets,
// set an item's fields and options from typed text, style, pane sections and alerts. An edit that cannot
// apply returns `{ error }` and leaves the draft as it was.
import type { TidemarkConfig, TidemarkWidgetId, TidemarkWidgetItem } from '../types'
import { ALERT_MAX, MAX_LINES, WIDGET_OPTIONS } from './config-model'
import type { OptionSpec } from './config-model'

export type Config = TidemarkConfig
export type Selection = { line: number; index: number }
export type Edit = { config: Config; selected?: Selection | null } | { error: string }

const itemAt = (c: Config, s: Selection | null): TidemarkWidgetItem | undefined => s ? c.lines[s.line]?.[s.index] : undefined

const withLines = (c: Config, lines: TidemarkWidgetItem[][]): Config => ({ ...c, lines })

// Moves the selected widget left or right in its line, or to the end of the line above or below; moving
// below the last line starts a new one (up to three). Emptied lines are dropped.
export function moveItem(c: Config, s: Selection, dir: 'left' | 'right' | 'up' | 'down'): Edit {
  const item = itemAt(c, s)
  if (!item) return { error: 'no widget selected' }
  const lines = c.lines.map(l => [...l])
  if (dir === 'left' || dir === 'right') {
    const to = s.index + (dir === 'left' ? -1 : 1)
    const line = lines[s.line]!
    if (to < 0 || to >= line.length) return { config: c, selected: s }
    line.splice(s.index, 1)
    line.splice(to, 0, item)
    return { config: withLines(c, lines), selected: { line: s.line, index: to } }
  }
  const to = s.line + (dir === 'up' ? -1 : 1)
  if (to < 0 || to >= MAX_LINES || (to === lines.length && lines[s.line]!.length === 1)) return { config: c, selected: s }
  if (to === lines.length) lines.push([])
  lines[s.line]!.splice(s.index, 1)
  lines[to]!.push(item)
  const kept = lines.filter(l => l.length > 0)
  const line = kept.indexOf(lines[to]!)
  return { config: withLines(c, kept), selected: { line, index: kept[line]!.length - 1 } }
}

export function removeItem(c: Config, s: Selection): Edit {
  if (!itemAt(c, s)) return { error: 'no widget selected' }
  if (c.lines.flat().length === 1) return { error: 'the band needs one widget' }
  const lines = c.lines.map((l, i) => (i === s.line ? l.filter((_, j) => j !== s.index) : l)).filter(l => l.length > 0)
  return { config: withLines(c, lines), selected: null }
}

// Adds a widget at the end of a line (the last one when the line does not exist).
export function addItem(c: Config, widget: TidemarkWidgetId, line: number): Edit {
  if (!Object.hasOwn(WIDGET_OPTIONS, widget)) return { error: `unknown widget ${widget}` }
  const at = Math.min(Math.max(line, 0), c.lines.length - 1)
  const lines = c.lines.map((l, i) => (i === at ? [...l, { widget }] : l))
  return { config: withLines(c, lines), selected: { line: at, index: lines[at]!.length - 1 } }
}

function patchItem(c: Config, s: Selection, patch: (item: TidemarkWidgetItem) => TidemarkWidgetItem): Edit {
  if (!itemAt(c, s)) return { error: 'no widget selected' }
  const lines = c.lines.map((l, i) => (i === s.line ? l.map((it, j) => (j === s.index ? patch(it) : it)) : l))
  return { config: withLines(c, lines), selected: s }
}

const without = <T extends object, K extends keyof T>(o: T, key: K): Omit<T, K> => {
  const { [key]: _, ...rest } = o
  return rest
}

export const toggleItem = (c: Config, s: Selection): Edit =>
  patchItem(c, s, it => (it.enabled === false ? without(it, 'enabled') : { ...it, enabled: false }))

// Text to a whole number in a range, or an error for the field.
export function toInt(text: string, min: number, max: number): number | { error: string } {
  const t = text.trim()
  const n = /^-?\d+$/.test(t) ? Number(t) : NaN
  if (!Number.isSafeInteger(n) || n < min || n > max) return { error: `a whole number from ${min} to ${max}` }
  return n
}

// Empty text restores the default priority.
export function setPriority(c: Config, s: Selection, text: string): Edit {
  if (text.trim() === '') return patchItem(c, s, it => without(it, 'priority'))
  const n = toInt(text, 0, 1000)
  return typeof n === 'number' ? patchItem(c, s, it => ({ ...it, priority: n })) : n
}

// `own`: the widget's own label; `none`: no label; text: that label.
export function setLabel(c: Config, s: Selection, label: string | null | undefined): Edit {
  return patchItem(c, s, it => (label === undefined ? without(it, 'label') : { ...it, label }))
}

// An option from the text a field holds or the value a picker chose, checked against its spec. A value equal
// to the default is dropped from the item.
export function setOption(c: Config, s: Selection, name: string, text: string): Edit {
  const item = itemAt(c, s)
  if (!item) return { error: 'no widget selected' }
  const specs = WIDGET_OPTIONS[item.widget]
  const spec: OptionSpec | undefined = Object.hasOwn(specs, name) ? specs[name] : undefined
  if (!spec) return { error: `unknown option ${name}` }
  let value: unknown
  switch (spec.kind) {
    case 'bool':
      if (text !== 'on' && text !== 'off') return { error: 'on or off' }
      value = text === 'on'
      break
    case 'enum':
      if (!spec.values.includes(text)) return { error: `one of ${spec.values.join(', ')}` }
      value = text
      break
    case 'int': {
      const n = toInt(text, spec.min, spec.max)
      if (typeof n !== 'number') return n
      value = n
      break
    }
    case 'string':
      value = text
      break
    case 'strings':
      value = text.split(',').map(t => t.trim()).filter(t => t !== '')
      break
  }
  return patchItem(c, s, it => {
    const options = { ...it.options, [name]: value }
    if (JSON.stringify(value) === JSON.stringify(spec.default)) delete options[name]
    return Object.keys(options).length > 0 ? { ...it, options } : without(it, 'options')
  })
}

// The value an option's field shows: the item's own, else the default.
export function optionText(spec: OptionSpec, value: unknown): string {
  const v = value === undefined ? spec.default : value
  if (spec.kind === 'bool') return v ? 'on' : 'off'
  if (spec.kind === 'strings') return (v as readonly string[]).join(', ')
  return String(v)
}

export function setStyle(c: Config, patch: Partial<Config['style']>): Edit {
  return { config: { ...c, style: { ...c.style, ...patch } } }
}

export function toggleSection(c: Config, id: string): Edit {
  return { config: { ...c, pane: { sections: c.pane.sections.map(s => (s.id === id ? { ...s, enabled: !s.enabled } : s)) } } }
}

// Moves a pane section one place up (the first goes last).
export function raiseSection(c: Config, id: string): Edit {
  const list = [...c.pane.sections]
  const i = list.findIndex(s => s.id === id)
  if (i < 0) return { error: `unknown section ${id}` }
  const [s] = list.splice(i, 1)
  list.splice(i === 0 ? list.length : i - 1, 0, s!)
  return { config: { ...c, pane: { sections: list } } }
}

// An alert threshold from typed text: percentages 0..100, the cache warning 0..3600 seconds.
export function setCompactAt(c: Config, text: string): Edit {
  const n = toInt(text, 1, 100)
  return typeof n === 'number' ? { config: { ...c, compact: { ...c.compact, at: n } } } : n
}

export function setAlert(c: Config, key: keyof typeof ALERT_MAX, text: string): Edit {
  const n = toInt(text, 0, ALERT_MAX[key])
  return typeof n === 'number' ? { config: { ...c, alerts: { ...c.alerts, [key]: n } } } : n
}

files.hooks/pane-rows.ts:
// Pure rows for the /tidemark pane: the sections the config lists, in its order, from the snapshot.
// Forecast formula after WeekToken / ccOverhead (MIT, shengyy).
import type { TidemarkEffort, TidemarkLimit, TidemarkSectionId, TidemarkSnapshot as Snapshot } from '../types'
import type { PaneRow } from './draw'
import { WIDGETS } from './widgets'
import type { Span, WidgetInput } from './widgets'
import { bar, dur, kshort, ktok, pctTier, quota, quotaWindow, spaced } from './widgets/kit'

// When a quota window runs out at its average pace so far, and the share used by its reset. None for a
// window of unknown length or reset, a reading older than 15 min (or 5% of the window), the window's first
// minutes, a passed reset, and 0% or 100% used.
export function quotaForecast(limit: TidemarkLimit, observedAt: number | null, now: number, model: string | null = null): { exhaustsAt: number; percentAtReset: number; resetFirst: boolean } | undefined {
  const window = quotaWindow(limit.kind, model).ms
  if (!window || !limit.resetsAt || observedAt === null || observedAt > now || now - observedAt > Math.max(15 * 60_000, window * 0.05)) return undefined
  const reset = Date.parse(limit.resetsAt)
  const elapsed = window - (reset - now)
  const used = limit.percentUsed / 100
  if (!Number.isFinite(reset) || elapsed <= Math.max(5 * 60_000, window * 0.001) || elapsed >= window || !(used > 0 && used < 1)) return undefined
  const exhaustsAt = now + Math.round((elapsed * (1 - used)) / used)
  return { exhaustsAt, percentAtReset: Math.round(((used * window) / elapsed) * 1000) / 10, resetFirst: exhaustsAt >= reset }
}

type SectionId = TidemarkSectionId
const SERVERS = 5
const dim = (text: string): Span => ({ text, role: 'dim' })
const row = (label: string, ...spans: (Span | false | undefined)[]): PaneRow => ({ label, spans: spaced(spans) })
const effortOf = (e: TidemarkEffort | null | undefined) => (e === null || e === undefined ? false : dim(`· effort ${e}`))
const input = (snap: Snapshot, now: number, options: Record<string, unknown> = {}): WidgetInput =>
  ({ snap, probes: {}, options, label: null, icons: 'text', now, env: {} })

const SECTIONS: Record<SectionId, { head: string; rows(s: Snapshot, now: number): PaneRow[] }> = {
  context: { head: 'Context', rows: context },
  cacheQuota: { head: 'Cache & quota', rows: cacheQuota },
  agents: { head: 'Session & agents', rows: agents },
}

// The enabled sections in the config's order, each a heading and its rows, or `no data yet`.
export function paneRows(snap: Snapshot, sections: { id: SectionId; enabled: boolean }[], now: number): PaneRow[] {
  return sections.filter(s => s.enabled).flatMap(({ id }) => {
    const rows = SECTIONS[id].rows(snap, now)
    return [{ head: SECTIONS[id].head }, ...(rows.length > 0 ? rows : [row('', dim('no data yet'))])]
  })
}

// The fill, the auto-compaction threshold and the tokens to go, /context's categories and the costliest MCP servers.
function context(s: Snapshot): PaneRow[] {
  const ctx = s.ctx
  if (!ctx || ctx.window <= 0) return []
  const out: PaneRow[] = []
  const used = ctx.tokens ?? ctx.estimate
  if (ctx.tokens !== undefined) {
    const pc = Math.trunc(ctx.percent ?? (ctx.tokens * 100) / ctx.window)
    out.push(row('window', { text: bar(pc, 10), tier: pctTier(pc), bar: { percent: pc } }, { text: `${pc}%`, tier: pctTier(pc) }, dim(`${ktok(ctx.tokens)} of ${ktok(ctx.window)}`)))
  } else if (ctx.estimate !== undefined) {
    const pc = Math.trunc((ctx.estimate * 100) / ctx.window)
    out.push(row('window', { text: bar(pc, 10), role: 'dim', bar: { percent: pc, dim: true } }, dim(`~${pc}% ~${ktok(ctx.estimate)} of ${ktok(ctx.window)}, estimated`)))
  }
  const at = ctx.compactAt
  if (at !== undefined && at > 0 && at < ctx.window) {
    out.push(row('compacts', dim(`at ${kshort(at)}`), used !== undefined && { text: `· ${kshort(Math.max(at - used, 0))} to go`, tier: pctTier((used * 100) / at) }))
  } else if (s.breakdown && !s.breakdown.autoCompact) out.push(row('compacts', dim('never: auto-compaction is off')))
  const b = s.breakdown
  if (b && b.rows.length > 0) {
    const total = b.rows.reduce((n, r) => n + r.tokens, 0)
    for (const r of [...b.rows].sort((x, y) => y.tokens - x.tokens)) {
      out.push(row('', { text: ktok(r.tokens), tier: pctTier((r.tokens * 100) / ctx.window) }, dim(`${Math.round((r.tokens * 100) / total)}%`), { text: r.name }))
    }
  }
  // The servers by their loaded tools, whatever /context calls their category.
  if (b && b.mcp.length > 0) {
    out.push(row('MCP', dim('servers')))
    for (const m of [...b.mcp].sort((x, y) => y.tokens - x.tokens).slice(0, SERVERS)) out.push(row('', dim(`  ${ktok(m.tokens)} ${m.server}`)))
    if (b.mcp.length > SERVERS) out.push(row('', dim(`  and ${b.mcp.length - SERVERS} more servers`)))
  }
  return out
}

// The cache's state and hit rate, the main conversation's tokens, every open quota window with its forecast.
function cacheQuota(s: Snapshot, now: number): PaneRow[] {
  const out: PaneRow[] = []
  const state = WIDGETS.cache.render(input(s, now))[0]
  if (state) out.push({ label: 'state', spans: state })
  const { input: uncached, output, read, write } = s.cacheStats
  const total = uncached + read + write
  if (total > 0) {
    const hit = Math.trunc((read * 100) / total)
    out.push(row('hit rate', { text: `${hit}%`, tier: pctTier(100 - hit) }, dim(`· read ${kshort(read)} · written ${kshort(write)} · uncached ${kshort(uncached)}`)))
  }
  if (total > 0 || output > 0) out.push(row('tokens', { text: `${kshort(total)} in · ${kshort(output)} out` }))
  for (const l of s.limits) {
    const spans = quota(WIDGETS.quota5h, input(s, now, { bar: true, showReset: true, mode: 'used' }), l)[0]
    if (!spans) continue
    out.push({ label: quotaWindow(l.kind, s.model).label, spans })
    const f = s.limitsLive ? quotaForecast(l, s.limitsAt, now, s.model) : undefined
    if (f) out.push(row('', dim(`≈${Math.round(f.percentAtReset)}% by reset · ${f.resetFirst ? 'reset first' : `limit in ≈${dur(f.exhaustsAt - now)}`}`)))
  }
  return out
}

// The session, then the last subagents, the latest first.
function agents(s: Snapshot): PaneRow[] {
  const out: PaneRow[] = []
  if (s.sessionId) out.push(row('session ID', dim(s.sessionId)))
  if (s.model) out.push(row('model', { text: s.model }, effortOf(s.effort)))
  const { input: uncached, output, read, write } = s.cacheStats
  if (uncached + read + write + output > 0) out.push(row('tokens', { text: `${kshort(uncached + read + write)} in · ${kshort(output)} out` }))
  for (const a of [...s.agents].reverse()) {
    out.push(
      row(a.label ?? 'agent', !!a.description?.trim() && { text: a.description.replace(/\s+/g, ' ').trim() }),
      row('agent ID', dim(a.id)),
      row('model', { text: a.model }, effortOf(a.effort)),
      row('tokens', { text: `${kshort(a.usage.input)} in · ${kshort(a.usage.output)} out` }, dim(`· ${kshort(a.usage.read)} cache read`)),
    )
  }
  return out
}

